  modal('Replanification groupée','<form onsubmit="iaBSaveReplan(event)"><input type="hidden" name="operationKey" value="planning-replan-'+crypto.randomUUID()+'"><div class="form-two"><label>Périmètre<select name="scope"><option value="day">Journée</option><option value="team">Équipe</option><option value="range">Plusieurs jours</option><option value="project">Chantier</option><option value="assignment">Affectation</option></select></label><label>Décaler de jours<input name="shiftDays" type="number" min="-365" max="365" value="1"></label><label>Date / journée<input name="date" type="date" value="'+esc(iaBPlanningAnchor||reference)+'"></label><label>Du<input name="from" type="date" value="'+esc(range.from)+'"></label><label>Au<input name="to" type="date" value="'+esc(range.to)+'"></label><label>Équipe<select name="teamId"><option value="">—</option>'+(teams||[]).map(item=>'<option value="'+esc(item.id)+'" '+(String(item.id)===team?'selected':'')+'>'+esc(item.name)+'</option>').join('')+'</select></label><label>Chantier<select name="projectId"><option value="">—</option>'+(jobs||[]).map(job=>'<option value="'+esc(job.id)+'" '+(String(job.id)===project?'selected':'')+'>'+esc(job.name)+'</option>').join('')+'</select></label><label>ID affectation<input name="assignmentId" placeholder="Affectation précise"></label><label>Nouveau chantier<select name="targetProjectId"><option value="">Inchangé</option>'+(jobs||[]).map(job=>'<option value="'+esc(job.id)+'">'+esc(job.name)+'</option>').join('')+'</select></label><label>Nouvelle équipe<select name="targetTeamId"><option value="">Inchangée</option>'+(teams||[]).map(item=>'<option value="'+esc(item.id)+'">'+esc(item.name)+'</option>').join('')+'</select></label></div><label>Motif<input name="reason" maxlength="500" placeholder="Pourquoi replanifier ?"></label><p class="subtle">Selon le périmètre choisi, OUVRANE déplace une affectation, une journée, une équipe, une période ou tout un chantier. Les conflits et indisponibilités restent bloquants.</p><div class="modal-actions"><button class="btn primary">Replanifier</button></div></form>');
