  modal('Nouvelle indisponibilité','<form onsubmit="iaBSaveAbsence(event)"><label>Personne<select name="personId" required>'+(people||[]).map(person=>'<option value="'+esc(person.id)+'">'+esc(person.name)+'</option>').join('')+'</select></label><div class="form-two"><label>Type<select name="type">'+[['absence','Absence'],['leave','Congé'],['sickness','Maladie'],['training','Formation'],['unavailable','Indisponible']].map(([v,l])=>'<option value="'+v+'">'+l+'</option>').join('')+'</select></label><label>Statut<select name="status"><option value="approved">Confirmé</option><option value="pending">En attente</option></select></label><label>Début<input name="startsAt" type="datetime-local" required value="'+start+'"></label><label>Fin<input name="endsAt" type="datetime-local" required value="'+end+'"></label></div><label>Motif<input name="reason" maxlength="500"></label><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>');
