async function iaBSaveBlock(event,id=''){event.preventDefault();const f=new FormData(event.target);try{await serverJson('/api/planning/blocks'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify({projectId:String(f.get('projectId')),startsAt:f.get('startsAt'),endsAt:f.get('endsAt'),type:f.get('type'),status:'active',responsiblePersonId:String(f.get('responsiblePersonId')||''),dueDate:String(f.get('dueDate')||''),reason:String(f.get('reason')||'')})});closeModal();await iaBLoadPlanning(true);toast(id?'Blocage mis à jour.':'Blocage chantier enregistré.')}catch(error){toast(error.message||'Blocage refusé.')}}
