function iaBCanViewJobFinance(){const access=globalThis.socleCurrentAccess||{},permissions=new Set(access.permissions||[]);if(access.owner||access.roleCode==='OWNER')return true;if(permissions.has('quotes.prices.view')||permissions.has('margins.view'))return true;if(typeof sessionAssignment==='function'){const sensitive=sessionAssignment()?.sensitive||{};return Boolean(sensitive.quotePrices||sensitive.jobMargins)}return false}
function iaBJobRowMarkup(job,team,lead,status){
  const reference=String(job.reference||job.ref||job.id),progress=Math.max(0,Math.min(100,Number(job.progress||0))),label='Ouvrir le dossier chantier '+reference+' · '+String(job.name||'');
  return '<tr class="ia-job-row" data-job-id="'+esc(job.id)+'"><td class="ia-job-cell ia-job-identity"><button type="button" class="ia-job-title-link" onclick="iaBOpenJobDetails('+iaBJobActionArgument(job.id)+')" onkeydown="if(event.target===this&&(event.key===\'Enter\'||event.key===\' \')){event.preventDefault();this.click()}"><strong>'+esc(job.name||'Chantier sans titre')+'</strong><span class="ia-job-reference">'+esc(reference)+'</span><span class="ia-job-mobile-meta">'+esc(reference)+' · '+esc(job.town||'Localité à renseigner')+'</span></button></td><td class="ia-job-cell ia-job-client" data-label="Client"><strong>'+esc(job.client||'Client à renseigner')+'</strong></td><td class="ia-job-cell ia-job-town" data-label="Localité"><span>'+esc(job.town||'—')+'</span></td><td class="ia-job-cell ia-job-status" data-label="Statut"><span class="badge">'+iaBStatusLabel(status)+'</span></td><td class="ia-job-cell ia-job-team" data-label="Équipe"><strong>'+esc(team?.name||'—')+'</strong></td><td class="ia-job-cell ia-job-progress-cell" data-label="Progression"><div class="ia-job-progress-value"><strong>'+progress+'%</strong><span class="ia-job-progressbar" aria-hidden="true"><i style="width:'+progress+'%"></i></span></div></td><td class="ia-job-cell ia-job-action" data-label="Actions"><button type="button" class="btn ia-job-open" onclick="iaBOpenJobDetails('+iaBJobActionArgument(job.id)+')" aria-label="'+esc(label)+'">Ouvrir</button></td></tr>';
}
function iaBJobDetailSummary(job){const key=String(job.id),scheduled=[...(iaBPlanningState.data?.assignments||[]),...(assignments||[])].filter(item=>String(item.job)===key),dateValues=[...new Set(scheduled.map(item=>String(item.date||'').slice(0,10)).filter(Boolean))].sort(),start=job.startDate||job.plannedStart||job.start||job.dateStart,end=job.endDate||job.plannedEnd||job.end||job.dateEnd,dates=dateValues.length?(dateValues.length===1?fullDate(dateValues[0]):fullDate(dateValues[0])+' – '+fullDate(dateValues.at(-1))):[start&&fullDate(start),end&&fullDate(end)].filter(Boolean).join(' – ')||'Non renseignées',teamNames=[...new Set(scheduled.map(item=>iaBTeam(item.team)?.name).filter(Boolean))];if(!teamNames.length&&job.teamId!==undefined&&job.teamId!==null){const assignedTeam=iaBTeam(job.teamId);if(assignedTeam?.name)teamNames.push(assignedTeam.name)}const quote=(quotes||[]).find(item=>String(item.job)===key&&item.status==='Accepté')||(quotes||[]).find(item=>String(item.job)===key),quoteAmount=quote&&typeof quoteGross==='function'?quoteGross(quote):null,financeAmount=quoteAmount??job.finance?.contractAmount??job.finance?.contractTotal??job.finance?.total??null,finance=iaBCanViewJobFinance()&&financeAmount!==null&&financeAmount!==undefined&&financeAmount!==''&&Number.isFinite(Number(financeAmount))?money(Number(financeAmount)):'Non disponible',taskRows=(typeof tasks!=='undefined'&&Array.isArray(tasks)?tasks:[]).filter(item=>String(item.job??item.projectId??item.linkId??'')===key),reminderRows=(typeof reminders!=='undefined'&&Array.isArray(reminders)?reminders:[]).filter(item=>String(item.linkId??'')===key&&String(item.linkType||'job')==='job'),taskCount=taskRows.length||reminderRows.length,documentsReady=typeof serverDocumentsState==='string'&&serverDocumentsState==='ready',documents=documentsReady&&typeof documentsForRelation==='function'?documentsForRelation('project',job.id).length:null,documentLabel=documents===null?'Documents selon vos droits':documents+' document(s) lié(s)';return '<section class="job-detail-summary" data-ia-b-job-summary aria-label="Résumé du chantier"><div class="job-detail-summary-grid"><div><small>Référence</small><strong>'+esc(job.reference||job.ref||job.id)+'</strong></div><div><small>Client</small><strong>'+esc(job.client||'Non renseigné')+'</strong></div><div><small>Adresse</small><strong>'+esc([job.address,job.town].filter(Boolean).join(', ')||'Non renseignée')+'</strong></div><div><small>Statut / phase</small><strong>'+esc(job.phase||job.status||iaBStatusLabel(iaBJobStatus(job)))+'</strong></div><div><small>Équipe</small><strong>'+esc(teamNames.join(', ')||'Non renseignée')+'</strong></div><div><small>Dates planifiées</small><strong>'+esc(dates)+'</strong></div><div><small>Montant</small><strong>'+esc(finance)+'</strong></div><div><small>Tâches / documents</small><strong>'+esc(taskCount+' tâche(s) · '+documentLabel)+'</strong></div></div><button type="button" class="btn job-open-workspace" data-open-job-workspace onclick="iaBOpenJobWorkspace('+iaBJobActionArgument(job.id)+')">Ouvrir le hub chantier <span aria-hidden="true">→</span></button></section>'}
function iaBJobStatus(job){const raw=String(job.phase||job.status||'').toLowerCase();if(raw.includes('arch'))return'archived';if(raw.includes('termin')||raw.includes('complete'))return'completed';if(raw.includes('bloq')||raw.includes('block'))return'blocked';if(raw.includes('plan'))return'planned';if(raw.includes('prépar')||raw.includes('prepar'))return'preparation';return'in_progress'}
function iaBStatusLabel(status){return({preparation:'Préparation',planned:'Planifié',in_progress:'En cours',blocked:'Bloqué',completed:'Terminé',archived:'Archivé'})[status]||status}
function iaBJobTeam(jobId){const list=(assignments||[]).filter(item=>String(item.job)===String(jobId)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));return list[0]?.team??null}
function iaBJobLead(jobId){const teamId=iaBJobTeam(jobId);if(teamId==null)return null;return iaBLeadForTeam(teamId,iaBPlanningAnchor||reference)?.personId??null}
function iaBSetJobFilter(key,value){iaBJobsFilters[key]=String(value||'');render()}
function iaBOpenJob(jobId){const job=(jobs||[]).find(item=>String(item.id)===String(jobId));if(!job)return;showJob(job.id)}
jobsView=function(){
  if(!iaBPlanningState.data&&!iaBPlanningState.loading)queueMicrotask(()=>iaBLoadPlanning());
  const towns=[...new Set((jobs||[]).map(job=>job.town).filter(Boolean))].sort(),leadIds=[...new Set((iaBPlanningState.data?.teamLeads||[]).map(row=>String(row.personId)))],q=iaBJobsFilters.q.toLowerCase();
  let list=(jobs||[]).filter(job=>{const status=iaBJobStatus(job),team=iaBJobTeam(job.id),lead=iaBJobLead(job.id);return(!iaBJobsFilters.status||status===iaBJobsFilters.status)&&(!iaBJobsFilters.team||String(team)===iaBJobsFilters.team)&&(!iaBJobsFilters.lead||String(lead)===iaBJobsFilters.lead)&&(!iaBJobsFilters.town||String(job.town||'')===iaBJobsFilters.town)&&(!q||(String(job.name||'')+' '+String(job.reference||'')+' '+String(job.client||'')+' '+String(job.town||'')).toLowerCase().includes(q))}).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'fr'));
  const shown=iaBJobsExpanded?list:list.slice(0,5),rows=shown.map(job=>{const status=iaBJobStatus(job),team=iaBTeam(iaBJobTeam(job.id)),lead=iaBPerson(iaBJobLead(job.id));return iaBJobRowMarkup(job,team,lead,status)}).join('');
  const table=rows?'<div class="ia-jobs-table-wrap"><table class="ia-jobs-table"><colgroup><col class="ia-job-col-name"><col class="ia-job-col-client"><col class="ia-job-col-town"><col class="ia-job-col-status"><col class="ia-job-col-team"><col class="ia-job-col-progress"><col class="ia-job-col-actions"></colgroup><thead><tr><th>Chantier</th><th>Client</th><th>Localité</th><th>Statut</th><th>Équipe</th><th>Progression</th><th>Ordre</th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty">Aucun chantier dans cette sélection.</div>';
  return heading('Chantiers','Recherche, filtres et dossiers opérationnels.',false)+'<div class="toolbar ia-b-filters"><input placeholder="Rechercher chantier, client, référence…" value="'+esc(iaBJobsFilters.q)+'" oninput="iaBSetJobFilter(\'q\',this.value)"><select aria-label="Statut du chantier" onchange="iaBSetJobFilter(\'status\',this.value)"><option value="">Tous les statuts</option>'+['preparation','planned','in_progress','blocked','completed','archived'].map(v=>'<option value="'+v+'" '+(v===iaBJobsFilters.status?'selected':'')+'>'+iaBStatusLabel(v)+'</option>').join('')+'</select><select aria-label="Équipe du chantier" onchange="iaBSetJobFilter(\'team\',this.value)"><option value="">Toutes les équipes</option>'+(teams||[]).map(team=>'<option value="'+esc(team.id)+'" '+(String(team.id)===iaBJobsFilters.team?'selected':'')+'>'+esc(team.name)+'</option>').join('')+'</select><select aria-label="Chef de chantier" onchange="iaBSetJobFilter(\'lead\',this.value)"><option value="">Tous les chefs</option>'+leadIds.map(id=>'<option value="'+esc(id)+'" '+(id===iaBJobsFilters.lead?'selected':'')+'>'+esc(iaBPerson(id)?.name||id)+'</option>').join('')+'</select><select aria-label="Localité du chantier" onchange="iaBSetJobFilter(\'town\',this.value)"><option value="">Toutes les localités</option>'+towns.map(town=>'<option '+(town===iaBJobsFilters.town?'selected':'')+'>'+esc(town)+'</option>').join('')+'</select></div><div class="ia-jobs-phase-targets" role="group" aria-label="Déposer un chantier sur une phase">'+['preparation','planned','in_progress','blocked','completed'].map(status=>'<button type="button" data-job-phase-target="'+status+'" onclick="iaBSetJobFilter(\'status\',\''+status+'\')">'+iaBStatusLabel(status)+'</button>').join('')+'</div><div class="section-heading ia-jobs-heading"><h2>'+list.length+' chantier(s)</h2><button class="btn primary" onclick="jobForm()">+ Nouveau chantier</button></div><section class="panel ia-jobs-list">'+table+(list.length>5?'<div class="ia-b-more"><button class="btn" onclick="iaBJobsExpanded=!iaBJobsExpanded;render()">'+(iaBJobsExpanded?'Réduire':'Afficher plus ('+(list.length-5)+')')+'</button></div>':'')+'</section>';
};

function iaBHubData(job){
  const jobAssignments=(assignments||[]).filter(item=>String(item.job)===String(job.id)).sort((a,b)=>String(b.date).localeCompare(String(a.date))),teamIds=[...new Set(jobAssignments.map(item=>String(item.team)))],peopleIds=[...new Set(jobAssignments.flatMap(item=>item.people||[]).map(String))];
  return{jobAssignments,teamIds,peopleIds};
}
function iaBHubTab(id,tab){
  const job=iaBJob(id);if(!job)return'';const data=iaBHubData(job),quoteRows=(quotes||[]).filter(q=>String(q.job)===String(id)),taskRows=(tasks||[]).filter(t=>String(t.job??t.projectId??t.linkId??'')===String(id));
  if(tab==='planning')return data.jobAssignments.length?data.jobAssignments.slice(0,12).map(item=>'<div class="detail-row"><span>'+esc(item.date)+' · '+esc(iaBTeam(item.team)?.name||'Équipe')+'</span><b>'+esc(item.startTime||'07:00')+'–'+esc(item.endTime||'16:00')+'</b></div>').join(''):'<p class="person-empty">Aucune affectation.</p>';
  if(tab==='team')return data.peopleIds.length?data.peopleIds.map(personId=>'<div class="detail-row"><span>'+esc(iaBPerson(personId)?.name||personId)+'</span><b>'+esc(iaBTeam(data.teamIds[0])?.name||'Équipe')+'</b></div>').join(''):'<p class="person-empty">Aucune équipe affectée.</p>';
  if(tab==='hours')return typeof timeRows==='function'?timeRows(job):'<p class="person-empty">Heures indisponibles.</p>';
  if(tab==='tasks')return '<p>'+taskRows.length+' tâche(s) liée(s) au chantier.</p>';
  if(tab==='problems')return '<p>'+taskRows.filter(t=>t.taskKind==='problem'||t.kind==='problem').length+' problème(s) identifié(s).</p>';
  if(tab==='photos')return '<p>'+((job.photos||[]).length)+' photo(s) dans le dossier.</p>';
  if(tab==='documents')return '<p>Documents : ouvrir le registre documentaire sécurisé du chantier.</p>';
  if(tab==='quotes')return '<p>'+quoteRows.length+' devis visible(s) pour ce chantier.</p>';
  if(tab==='invoices')return '<p>Factures : consultation via Comptabilité selon vos droits.</p>';
  if(tab==='purchases')return '<p>Achats : consultation via les commandes fournisseur du chantier.</p>';
  if(tab==='assets')return '<p>Matériel : véhicules et outillage affectés via le planning.</p>';
  if(tab==='history')return '<p class="ia-b-planning-history-loading">Chargement des changements du planning…</p>';
  return '<div class="detail-row"><span>Statut</span><b>'+iaBStatusLabel(iaBJobStatus(job))+'</b></div><div class="detail-row"><span>Localité</span><b>'+esc(job.town||'—')+'</b></div><div class="detail-row"><span>Avancement</span><b>'+Number(job.progress||0)+'%</b></div>';
}
function iaBHistoryValue(value){if(!value||typeof value!=='object')return'';const parts=[];if(value.date)parts.push(value.date);if(value.team_id)parts.push('équipe '+(iaBTeam(value.team_id)?.name||value.team_id));if(value.project_id)parts.push('chantier '+(iaBJob(value.project_id)?.name||value.project_id));if(value.status)parts.push(value.status==='cancelled'?'annulée':value.status);if(value.start_time||value.end_time)parts.push((value.start_time||'')+'–'+(value.end_time||''));return parts.join(' · ')}
function iaBHistoryMarkup(events){const labels={'assignment.created':'Affectation créée','assignment.updated':'Affectation modifiée','assignment.cancelled':'Affectation annulée','planning.replanned':'Affectation replanifiée','planning.block.created':'Blocage ajouté','planning.block.updated':'Blocage modifié','planning.block.cancelled':'Blocage annulé'};return events.length?'<div class="ia-b-planning-history">'+events.map(event=>'<article class="ia-b-planning-history-row"><div><strong>'+esc(labels[event.action]||'Planning modifié')+'</strong><span>'+esc(event.actorName||'Utilisateur')+' · '+esc(event.createdAt||'')+'</span></div><small>'+esc(iaBHistoryValue(event.oldValues))+(event.oldValues&&event.newValues?' → ':'')+esc(iaBHistoryValue(event.newValues))+'</small></article>').join('')+'</div>':'<p class="person-empty">Aucun changement de planning enregistré pour ce chantier.</p>'}
function iaBRenderHubTab(id,tab){const root=document.querySelector('[data-ia-b-job-hub-body]');if(!root)return;root.innerHTML=iaBHubTab(id,tab);if(tab!=='history')return;const token=crypto.randomUUID();root.dataset.historyRequest=token;serverJson('/api/projects/'+encodeURIComponent(String(id))+'/planning-history').then(result=>{if(root.dataset.historyRequest===token)root.innerHTML=iaBHistoryMarkup(result.events||[])}).catch(error=>{if(root.dataset.historyRequest===token)root.innerHTML='<p class="notice">'+esc(error.message||'Historique indisponible.')+'</p>'})}
if(typeof showJob==='function'){
  const iaBShowJobBase=showJob;
  showJob=function(id){const job=(jobs||[]).find(item=>String(item.id)===String(id));if(!job)return;iaBShowJobBase(job.id);queueMicrotask(()=>{const root=document.querySelector('#modalbody .modal-inner');if(!root)return;if(!root.querySelector('[data-ia-b-job-summary]'))root.insertAdjacentHTML('afterbegin',iaBJobDetailSummary(job));if(root.querySelector('[data-ia-b-job-hub]'))return;const tabs=[['overview','Vue générale'],['planning','Planning'],['team','Équipe'],['hours','Heures'],['tasks','Tâches'],['problems','Problèmes'],['photos','Photos'],['documents','Documents'],['quotes','Devis'],['invoices','Factures'],['purchases','Achats'],['assets','Matériel'],['history','Historique']];root.insertAdjacentHTML('beforeend','<section class="job-detail-section ia-b-job-hub" data-ia-b-job-hub><div class="section-heading"><h3>Hub chantier</h3><span class="badge">IA-B</span></div><div class="ia-b-hub-tabs">'+tabs.map(([key,label])=>'<button type="button" class="link" onclick="iaBRenderHubTab('+iaBJobActionArgument(job.id)+',\''+key+'\')">'+label+'</button>').join('')+'</div><div data-ia-b-job-hub-body>'+iaBHubTab(job.id,'overview')+'</div></section>')})};
}
